"use client";
import { useMorph } from "@/lib/cojeev-motion/use-morph";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { useFlowGroup } from "@/lib/cojeev-motion/use-flow";
import { useFlowPress } from "@/lib/cojeev-motion/flow-press";
import { cn } from "@/lib/utils";
import {
  controlRadiusStyle,
  type ControlRadius,
} from "@/lib/cojeev/control-appearance";

const ItemVariants = cva(
  "v-item [display:flex] [align-items:center] [gap:var(--s-4)] [padding:var(--row-pad)] [border-radius:var(--r-card-sm)] [background:var(--card-2)] [min-height:var(--item-h)] [text-align:left] [width:100%] [transition:background_var(--t-micro)]",
  {
    variants: {
      variant: {
        default: "",
        selected:
          "-selected [background:var(--sel-bg)] [--muted-foreground:var(--muted-foreground-ink)] [color:var(--sel-ink)] [box-shadow:inset_0_0_0_1px_var(--sel-edge)]",
        flat: "-flat [background:transparent] [padding:var(--s-3)_0] [min-height:56px] [border-radius:0]",
      },
      size: { default: "" },
    },
    defaultVariants: { variant: "default", size: "default" },
  },
);
export type ItemProps = React.ComponentProps<"button"> &
  VariantProps<typeof ItemVariants> & {
    as?: React.ElementType;
    appearance?: "ledger" | "cover" | "detail";
    radius?: ControlRadius;
  };
export function Item({
  ref: externalMorphRef,
  as: Tag = "button",
  className,
  variant,
  size,
  appearance,
  radius,
  style,
  ...props
}: ItemProps) {
  const ownedMorphRef = useMorph<HTMLButtonElement>("nav", externalMorphRef);
  const pressRef = useFlowPress(ownedMorphRef);
  return (
    <Tag
      ref={pressRef}
      data-slot="item-item"
      data-part="item"
      data-appearance={appearance}
      data-morph={appearance ? "both" : undefined}
      data-r={appearance ? "css" : undefined}
      type={Tag === "button" ? "button" : undefined}
      className={cn(ItemVariants({ variant, size }), className)}
      style={{ ...controlRadiusStyle(radius), ...style }}
      {...props}
    />
  );
}

const ItemGroupVariants = cva("v-list [display:grid] [gap:var(--s-2)]", {
  variants: {
    variant: {
      default: "",
      grouped:
        "-grouped [gap:0] [background:var(--card)] [border-radius:var(--r-card)] [padding:var(--s-2)]",
    },
    size: { default: "" },
  },
  defaultVariants: { variant: "default", size: "default" },
});
export type ItemGroupProps = React.ComponentProps<"div"> &
  VariantProps<typeof ItemGroupVariants> & { as?: React.ElementType };
export function ItemGroup({
  as: Tag = "div",
  ref: externalRef,
  className,
  variant,
  size,
  ...props
}: ItemGroupProps) {
  const ref = useFlowGroup<HTMLDivElement>(externalRef);
  const ownedMorphRef = useMorph<HTMLDivElement>("cards", ref);
  return (
    <Tag
      ref={ownedMorphRef}
      data-slot="item"
      data-part="root"
      className={cn(ItemGroupVariants({ variant, size }), className)}
      {...props}
    />
  );
}

const ItemContentVariants = cva(
  "v-item__body [flex:1] [min-width:0] [display:grid] [gap:2px]",
  {
    variants: { variant: { default: "" }, size: { default: "" } },
    defaultVariants: { variant: "default", size: "default" },
  },
);
export type ItemContentProps = React.ComponentProps<"div"> &
  VariantProps<typeof ItemContentVariants> & { as?: React.ElementType };
export function ItemContent({
  as: Tag = "div",
  className,
  variant,
  size,
  ...props
}: ItemContentProps) {
  return (
    <Tag
      data-slot="item-content"
      data-part="content"
      className={cn(ItemContentVariants({ variant, size }), className)}
      {...props}
    />
  );
}

const ItemTitleVariants = cva(
  "v-item__title [font-size:16px] [font-weight:600] [line-height:1.25] [display:-webkit-box] [-webkit-line-clamp:2] [-webkit-box-orient:vertical] [overflow:hidden]",
  {
    variants: { variant: { default: "" }, size: { default: "" } },
    defaultVariants: { variant: "default", size: "default" },
  },
);
export type ItemTitleProps = React.ComponentProps<"div"> &
  VariantProps<typeof ItemTitleVariants> & { as?: React.ElementType };
export function ItemTitle({
  as: Tag = "div",
  className,
  variant,
  size,
  ...props
}: ItemTitleProps) {
  return (
    <Tag
      data-slot="item-title"
      data-part="title"
      className={cn(ItemTitleVariants({ variant, size }), className)}
      {...props}
    />
  );
}

const ItemDescriptionVariants = cva(
  "v-item__sub [font-size:var(--fs-meta)] [color:var(--muted-foreground)] [line-height:1.3]",
  {
    variants: { variant: { default: "" }, size: { default: "" } },
    defaultVariants: { variant: "default", size: "default" },
  },
);
export type ItemDescriptionProps = React.ComponentProps<"div"> &
  VariantProps<typeof ItemDescriptionVariants> & { as?: React.ElementType };
export function ItemDescription({
  as: Tag = "div",
  className,
  variant,
  size,
  ...props
}: ItemDescriptionProps) {
  return (
    <Tag
      data-slot="item-description"
      data-part="description"
      className={cn(ItemDescriptionVariants({ variant, size }), className)}
      {...props}
    />
  );
}

const ItemTrailingVariants = cva(
  "v-time [display:inline-flex] [align-items:center] [white-space:nowrap] [flex:none] [height:26px] [padding:0_12px] [border-radius:var(--r-pill)] [font-size:12px] [font-weight:500] [font-variant-numeric:tabular-nums] [background:var(--v-canvas)]",
  {
    variants: {
      variant: {
        default: "",
        blue: "-blue [background:var(--v-blue)] [color:var(--v-on-accent)]",
        pink: "-pink [background:var(--v-pink)] [color:var(--v-on-accent)]",
        olive: "-olive [background:var(--v-olive)] [color:var(--v-on-accent)]",
        yellow:
          "-yellow [background:var(--v-yellow)] [color:var(--v-on-accent)]",
      },
      size: { default: "" },
    },
    defaultVariants: { variant: "default", size: "default" },
  },
);
export type ItemTrailingProps = React.ComponentProps<"span"> &
  VariantProps<typeof ItemTrailingVariants> & { as?: React.ElementType };
export function ItemTrailing({
  ref: externalMorphRef,
  as: Tag = "span",
  className,
  variant,
  size,
  ...props
}: ItemTrailingProps) {
  const ownedMorphRef = useMorph<HTMLSpanElement>("pills", externalMorphRef);
  return (
    <Tag
      ref={ownedMorphRef}
      data-slot="item-trailing"
      data-part="trailing"
      className={cn(ItemTrailingVariants({ variant, size }), className)}
      {...props}
    />
  );
}

@layer cojeev-states {
/* Orthogonal authored class modifiers remain composable with CVA axes. */
.v-time[data-slot].-blue {
  background: var(--v-blue);
  color: var(--v-on-accent);
}
.v-time[data-slot].-pink {
  background: var(--v-pink);
  color: var(--v-on-accent);
}
.v-time[data-slot].-olive {
  background: var(--v-olive);
  color: var(--v-on-accent);
}
.v-time[data-slot].-yellow {
  background: var(--v-yellow);
  color: var(--v-on-accent);
}
.v-item[data-slot].-selected {
  background: var(--sel-bg);
  --muted-foreground: var(--muted-foreground-ink);
  color: var(--sel-ink);
  box-shadow: inset 0 0 0 1px var(--sel-edge);
}
.v-item[data-slot].-flat {
  background: transparent;
  padding: var(--s-3) 0;
  min-height: 56px;
  border-radius: 0;
}
.v-list[data-slot].-grouped {
  gap: 0;
  background: var(--card);
  border-radius: var(--r-card);
  padding: var(--s-2);
}

/* Authored contextual and pseudo-element rules, scoped to component-owned roots. */
.v-time[data-slot][data-morph] {
  --mfill: var(--v-canvas);
}
.v-time[data-slot].-blue[data-morph] {
  --mfill: var(--v-blue);
}
.v-time[data-slot].-pink[data-morph] {
  --mfill: var(--v-pink);
}
.v-time[data-slot].-olive[data-morph] {
  --mfill: var(--v-olive);
}
.v-time[data-slot].-yellow[data-morph] {
  --mfill: var(--v-yellow);
}
[data-colourful="1"] .v-item[data-slot]:not(.-selected) {
  background: color-mix(in oklab, var(--v-blue-soft) 40%, var(--card-2));
}
.v-item[data-slot]:hover {
  background: color-mix(in oklab, var(--card-2) 94%, var(--v-ink));
}
.v-item[data-slot].-selected .v-disk {
  background: var(--v-canvas);
  color: var(--v-text);
}
.v-list[data-slot].-grouped .v-item {
  background: transparent;
  min-height: 56px;
}
.v-list[data-slot].-grouped .v-item:hover {
  background: var(--card-2);
}
@media (max-width: 640px) {
  .v-item__title[data-slot] {
    overflow-wrap: anywhere;
  }
}
.v-item[data-slot].-selected .v-item__sub {
  color: rgba(17, 17, 17, 0.66);
}
.v-item[data-slot].-selected .v-item__sub {
  color: rgba(17, 17, 17, 0.66);
}
.v-item[data-slot].-selected .v-help {
  color: rgba(17, 17, 17, 0.72);
}
:root[data-mode="dark"] .v-item[data-slot].-selected {
  color: var(--sel-ink);
}
:root[data-mode="dark"] .v-item[data-slot].-selected .v-item__sub {
  color: var(--v-text-2);
}
.v-item__body[data-slot] {
  box-shadow: none;
  border: 0;
}
.v-item[data-slot] .v-time {
  flex: none;
}
.v-item[data-slot] {
  min-width: 0;
  gap: var(--s-3);
}
.v-item__body[data-slot] {
  min-width: 0;
}
.v-item__title[data-slot] {
  overflow-wrap: anywhere;
  line-height: 1.4;
}
.v-item__sub[data-slot] {
  min-width: 0;
  overflow-wrap: anywhere;
}
.v-item[data-slot] :is([data-slot="item-actions"], [data-slot="item-media"]) {
  flex-shrink: 0;
}

/* Authored collection layouts; legacy flat/selected rows remain independent. */
.v-item[data-slot][data-appearance] {
  --item-face: var(--v-paper);
  --mfill: var(--item-face);
  --mstroke: var(--v-edge);
  background: var(--item-face);
  color: var(--v-text);
  border-radius: var(--v-control-radius, 16px);
  padding: 20px;
  gap: 18px;
  box-shadow: inset 0 0 0 1px var(--v-edge);
  transition: color var(--t-micro);
  transform: none;
  min-height: 44px;
}
.v-item[data-slot][data-appearance].-selected {
  --item-face: var(--v-blue-soft);
  --mstroke: var(--v-blue);
}
.v-item[data-slot][data-appearance] .v-item__sub {
  color: var(--v-text-2);
  font-size: 13px;
  line-height: 1.6;
}
.v-item[data-slot][data-appearance]:has(> svg.v-morph) {
  background: transparent;
  box-shadow: none;
}
.v-item[data-slot][data-appearance]:is(:hover, :active) {
  background: var(--item-face);
  transform: none;
}
.v-item[data-slot][data-appearance]:is(:hover, :active):has(> svg.v-morph) {
  background: transparent;
}
.v-item[data-slot][data-appearance]:disabled {
  --item-face: var(--v-disabled-face);
  --mstroke: var(--v-disabled-edge);
  color: var(--v-disabled-ink);
  cursor: not-allowed;
}
.v-item[data-slot][data-appearance]:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
}
.v-item-example {
  padding-inline: 16px;
  width: 100%;
  max-width: 670px;
  margin-inline: auto;
  display: grid;
  gap: 24px;
  color: var(--v-text);
}
.v-item-example header {
  display: grid;
  gap: 12px;
}
.v-item-example header > span {
  font-size: 10px;
  letter-spacing: 0.08em;
  color: var(--v-text-3);
}
.v-item-example h3 {
  font: 500 28px/1.25 var(--font-display);
  margin: 0;
}
.v-item-example p {
  margin: 0;
  font-size: 13px;
  line-height: 1.65;
  color: var(--v-text-2);
}
.v-item-example__list[data-slot] {
  gap: 14px;
}
.v-item-example__index {
  font-size: 11px;
  color: var(--v-text-3);
  font-variant-numeric: tabular-nums;
  align-self: start;
  padding-top: 4px;
}
.v-item-example__kind {
  font-size: 10px;
  color: var(--v-text-3);
  letter-spacing: 0.03em;
}
.v-item-example .v-item__body {
  gap: 7px;
}
.v-item-example .v-item__title {
  font: 500 20px/1.3 var(--font-display);
}
.v-item-example__count {
  font-size: 11px;
  color: var(--v-text-3);
  margin-top: 4px;
}
.v-item-example__mark[data-slot] {
  padding: 0;
  width: 32px;
  height: 32px;
  border: 1px solid var(--v-edge);
  background: transparent;
  display: grid;
  place-items: center;
  color: var(--v-text);
}
.v-item-example .-selected .v-item-example__mark {
  background: var(--v-blue);
  color: var(--v-on-accent);
  border-color: transparent;
}
.v-item-example [data-appearance="cover"] {
  display: grid;
  grid-template-columns: 128px minmax(0, 1fr) 32px;
  position: relative;
}
.v-item-example [data-appearance="cover"] .v-item-example__index {
  display: none;
}
.v-item-example__cover {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
  pointer-events: none;
}
.v-item-example [data-appearance="detail"] {
  display: grid;
  gap: 20px;
  padding: 24px;
}
.v-item-example__detail-content {
  display: flex;
  gap: 18px;
}
.v-item-example__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  padding-top: 16px;
  border-top: 1px solid var(--v-edge);
  justify-content: space-between;
}
.v-item-example__actions .v-btn {
  min-height: 44px;
}
.v-item-example__legacy {
  border-top: 1px solid var(--v-edge);
  padding-top: 12px;
  font-size: 12px;
}
.v-item-example__legacy summary {
  min-height: 44px;
  cursor: pointer;
}
@media (max-width: 540px) {
  .v-item-example [data-appearance] {
    gap: 12px;
    padding: 16px;
  }
  .v-item-example [data-appearance="cover"] {
    grid-template-columns: 76px minmax(0, 1fr);
    align-items: start;
  }
  .v-item-example [data-appearance="cover"] .v-item-example__mark {
    grid-column: 1;
    grid-row: 2;
  }
  .v-item-example [data-appearance="cover"] .v-item__body {
    grid-column: 2;
    grid-row: 1 / span 2;
  }
  .v-item-example [data-appearance="ledger"] .v-item-example__index {
    display: none;
  }
  .v-item-example .v-item__title {
    font-size: 19px;
  }
}

}

@layer cojeev-states {
/* One inherited corner contract, with a readable cap for multiline/native fields. */
:is(.v-input,.v-igroup,.v-select,.v-native,.v-number-input,.v-btn) {
  border-radius: var(--v-control-radius, var(--r-pill));
}
:is(.v-textarea,.v-composer,.v-native,.v-multi-select__trigger) {
  border-radius: min(var(--v-control-radius, 20px), 20px);
}
.v-btn[data-control-shape="card"] { border-radius: 12px; }
.v-btn[data-control-shape="pill"] { border-radius: var(--r-pill); }

/* A Field can own the treatment for its immediate shell; explicit child paint wins. */
:root .v-native[data-appearance] { padding-inline-end:40px; }
:root .v-native[data-appearance][size]:not([size="1"]) { padding-inline:8px; }
[data-slot="field"][data-appearance="contour"] { --v-field-face: var(--v-canvas); }
:root [data-appearance="contour"]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger),
:root [data-slot="field"][data-appearance="contour"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  background-color: var(--v-canvas);
  color: var(--v-text);
  box-shadow: inset 0 0 0 1px var(--v-edge);
}
:root [data-appearance="editorial"]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger),
:root [data-slot="field"][data-appearance="editorial"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  border-radius: 0;
  background-color: transparent;
  color: var(--v-text);
  box-shadow: inset 0 -1px 0 var(--v-edge);
  padding-inline: 2px;
}
:root [data-slot="field"][data-appearance="inset"] {
  padding: 14px 16px;
  border-radius: min(var(--v-control-radius, 20px), 20px);
  background: var(--v-beige);
  color: var(--v-text);
  box-shadow: inset 0 1px 2px color-mix(in oklab, var(--v-text) 9%, transparent);
  gap: 6px;
}
:root [data-appearance="inset"]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger) {
  background-color: var(--v-beige);
  color: var(--v-text);
  box-shadow: inset 0 1px 2px color-mix(in oklab, var(--v-text) 12%, transparent);
}
:root [data-slot="field"][data-appearance="inset"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  background: transparent;
  box-shadow: none;
  padding-inline: 0;
}
:root [data-slot="field"][data-appearance="inset"] [data-slot="field-label"] { color: var(--v-text-2); }
:root [data-slot="field"][data-appearance="inset"]:focus-within { outline: 2px solid var(--v-brand); outline-offset: 2px; }
:root [data-appearance]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger):focus-within,
:root [data-slot="field"][data-appearance] :is(.v-input,.v-igroup,.v-textarea):focus-within {
  outline: 2px solid var(--v-brand);
  outline-offset: 3px;
}
:root [data-slot="field"][data-appearance="inset"] :is(.v-input,.v-igroup,.v-textarea):focus-within { outline: none; }
:root [data-appearance]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger):is(:disabled,[data-disabled="true"],:has(input:disabled)),
:root [data-slot="field"][data-appearance] :is(.v-input,.v-igroup,.v-textarea):is(:disabled,:has(input:disabled)) {
  background: var(--v-disabled-face);
  color: var(--v-disabled-ink);
  box-shadow: inset 0 0 0 1px var(--v-disabled-edge);
  cursor: not-allowed;
}
:root [data-slot="field"][data-appearance][data-state="error"],
:root [data-appearance]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger):is([aria-invalid="true"],[data-invalid="true"],:has([aria-invalid="true"])) {
  outline: 2px solid var(--v-danger-fill);
  outline-offset: 3px;
}
:root [data-slot="field"][data-appearance][data-state="error"] [role="alert"] { color: var(--v-danger-ink); }

.v-form-example { display: grid; gap: 20px; width: 100%; min-width: 0; max-width: 480px; margin-inline: auto; }
.v-form-example__intro { display: grid; gap: 5px; }
.v-form-example__intro strong { font-family: var(--font-display, inherit); font-size: 22px; font-weight: 500; }
.v-form-example__intro p { margin: 0; color: var(--v-text-2); font-size: 13px; line-height: 1.5; }
.v-form-example__status { min-height: 1.5em; margin: 0; font-size: 12px; color: var(--v-text-2); overflow-wrap: anywhere; }
.v-form-example__footer { display: flex; gap: 10px; align-items: center; justify-content: space-between; }

/* Composer owns one surface, while the actual textarea keeps native editing. */
:root .v-composer[data-appearance] { border-radius:min(var(--v-control-radius,20px),20px); background:var(--v-canvas); color:var(--v-text); box-shadow:inset 0 0 0 1px var(--v-edge); }
:root .v-composer[data-appearance="inset"] { background:var(--v-beige); box-shadow:inset 0 1px 2px color-mix(in oklab,var(--v-text) 12%,transparent); }
:root .v-composer[data-appearance="editorial"] { border-radius:0; background:transparent; box-shadow:inset 0 -1px 0 var(--v-edge); }
:root .v-composer[data-appearance] .v-textarea:is(:focus,:hover,:not(:focus)) { background:transparent; box-shadow:none; outline:0; border-radius:0; resize:vertical; }
:root .v-composer[data-appearance] .v-textarea-scroll > textarea { padding-inline-end:30px; }
:root [data-slot="field"][data-appearance] [data-slot="input-group"] .v-textarea { background:transparent; box-shadow:none; outline:0; border:0; border-radius:0; }
:root .v-composer[data-appearance]:focus-within { outline:2px solid var(--v-brand); outline-offset:3px; }
:root [data-slot="field"][data-appearance="inset"] .v-composer[data-appearance] { background:transparent; box-shadow:none; outline:0; }
.v-form-example[data-form-example="field"] { max-width:600px; }
.v-form-example [data-slot="field-label"] { font-size:14px; line-height:1.5; }
.v-form-example [data-slot="field-description"] { font-size:13px; margin:0; }
.v-form-example__footer > .v-btn, .v-form-example [data-slot="textarea-composer-bar"] > .v-btn { min-height:44px; }
.v-form-example [data-slot="textarea-composer-bar"] { justify-content:space-between; flex-wrap:wrap; gap:12px; padding:10px 12px; border-top:1px solid var(--v-border); }
.v-form-example__allowance { height:4px; border-radius:4px; overflow:hidden; background:var(--v-beige); margin-top:-8px; }
.v-form-example__allowance > span { display:block; height:100%; max-width:100%; border-radius:inherit; background:var(--v-blue-deep); }
.v-form-example__label-row { display:flex; align-items:baseline; flex-wrap:wrap; gap:8px; justify-content:space-between; }
.v-form-example__label-row > span { font-size:12px; color:var(--v-text-2); }
.v-form-example__hint { margin:0; color:var(--v-text-2); font-size:13px; line-height:1.5; }
/* Editorial draws only the focus edge: no moving caret, label or hit area. */
:root [data-appearance="editorial"]:is(.v-input,.v-igroup,.v-textarea,.v-composer),
:root [data-slot="field"][data-appearance="editorial"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  background-image:linear-gradient(var(--v-brand),var(--v-brand)); background-repeat:no-repeat; background-position:left bottom; background-size:0% 2px;
  transition:background-size var(--t-micro) var(--enter);
}
:root [data-appearance="editorial"]:is(.v-input,.v-igroup,.v-textarea,.v-composer):focus-within,
:root [data-slot="field"][data-appearance="editorial"] :is(.v-input,.v-igroup,.v-textarea):focus-within { background-size:100% 2px; outline:0; }
@media(prefers-reduced-motion:reduce) { :root [data-slot="field"] :is(.v-input,.v-igroup,.v-textarea,.v-composer) { transition:none; } }

